-- Modify "finance_facts" table
ALTER TABLE "finance_facts" ADD CONSTRAINT "finance_facts_status_audit_bundle" CHECK ((((status)::text = 'DRAFT'::text) AND (posted_at IS NULL) AND (posted_by IS NULL) AND (settled_at IS NULL) AND (settled_by IS NULL)) OR (((status)::text = 'POSTED'::text) AND (posted_at IS NOT NULL) AND (posted_by IS NOT NULL) AND (settled_at IS NULL) AND (settled_by IS NULL)) OR (((status)::text = 'SETTLED'::text) AND (posted_at IS NOT NULL) AND (posted_by IS NOT NULL) AND (settled_at IS NOT NULL) AND (settled_by IS NOT NULL)) OR (((status)::text = 'CANCELLED'::text) AND (settled_at IS NULL) AND (settled_by IS NULL) AND (((posted_at IS NULL) AND (posted_by IS NULL)) OR ((posted_at IS NOT NULL) AND (posted_by IS NOT NULL)))));
-- Modify "outsourcing_facts" table
ALTER TABLE "outsourcing_facts" ADD CONSTRAINT "outsourcing_facts_status_audit_bundle" CHECK ((((status)::text = 'DRAFT'::text) AND (posted_at IS NULL) AND (posted_by IS NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancel_reason IS NULL)) OR (((status)::text = 'POSTED'::text) AND (posted_at IS NOT NULL) AND (posted_by IS NOT NULL) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancel_reason IS NULL)) OR (((status)::text = 'CANCELLED'::text) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL) AND (cancel_reason IS NOT NULL) AND ((length(TRIM(BOTH FROM cancel_reason)) >= 1) AND (length(TRIM(BOTH FROM cancel_reason)) <= 255)) AND (((posted_at IS NULL) AND (posted_by IS NULL)) OR ((posted_at IS NOT NULL) AND (posted_by IS NOT NULL)))));
